  "claim": {
    "component_id": "C028",
    "value": "Logging overhead for the proposed instrumentation canary must be bounded.",
    "scope": "Applies to the small canary proposed if existing evidence cannot discriminate; the numerical bound is unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P012",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P012 explicitly makes bounded logging overhead a constraint on the conditional instrumentation canary."
    }
  },
  "signal_basis": {
    "component_id": "C028_signal_basis",
    "value": "When existing evidence cannot discriminate, the operation proposes a small instrumentation canary with bounded logging overhead. Acceptable instrumentation overhead is defined before deployment against comparable baseline traffic, and the canary is reverted if bounds are breached or monitoring cannot enforce them.",
    "scope": "The proposed instrumentation canary and its overhead controls; no numerical threshold or observed safety result is asserted.",
    "provenance": {
      "refs": [
        {
          "source_id": "P012",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the proposal's trigger, overhead constraint, baseline-based bounds and enforcement rule."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C028_stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is an explicit operational constraint, not an inference requiring an unresolved empirical relation."
    }
  },
  "rationale": "The claim faithfully states a requirement imposed by the described operation. It does not infer that logging overhead is already acceptable or that the canary will succeed. Within its conditional scope, the requirement is licensed directly.",
  "uncertainty": "The numerical overhead bound remains unspecified, as the claim acknowledges; this does not undermine the requirement to bound it.",
